package org.rabochaya.projects;

import android.app.*;import android.content.*;import android.os.Bundle;import android.view.*;import android.widget.*;
import org.w3c.dom.Element;import java.util.*;import java.util.concurrent.*;

/** Local per-project folders and batch operations; file import/export remains in ProjectsActivity. */
public final class ObjectManagerActivity extends Activity {
 private long project;private String folder="",expected;private Element snapshot;private List<ObjectTree.Row> rows=Collections.emptyList();
 private ObjectListing listing;private ObjectListing.Options viewOptions=ObjectListing.Options.defaults();private Button searchButton,dateButton;private TextView selectionInfo,viewInfo;private final Set<String> shownKeys=new HashSet<>();
 private final Set<String> selected=new LinkedHashSet<>();private final ExecutorService worker=Executors.newSingleThreadExecutor();
 private boolean busy,disposed,refreshOnResume;private TextView status,path;private Button actions,up;private ListView list;private Rows adapter;
 public static void open(Activity parent,long project){parent.startActivity(new Intent(parent,ObjectManagerActivity.class).putExtra("project",project));}
 protected void onCreate(Bundle state){setTheme((getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK)==android.content.res.Configuration.UI_MODE_NIGHT_YES?android.R.style.Theme_Material_NoActionBar:android.R.style.Theme_Material_Light_NoActionBar);super.onCreate(state);project=getIntent().getLongExtra("project",-1);
  restoreView();if(state!=null){folder=state.getString("folder","");expected=state.getString("token");}
  LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(12,12,12,12);setContentView(root);watchFont(root);
  LinearLayout header=new LinearLayout(this);header.setOrientation(1);ScrollView headerScroll=new ScrollView(this){protected void onMeasure(int width,int height){int available=View.MeasureSpec.getSize(height);int limit=Math.max(WorkspaceUi.dp(ObjectManagerActivity.this,48),available-WorkspaceUi.dp(ObjectManagerActivity.this,192));super.onMeasure(width,View.MeasureSpec.makeMeasureSpec(limit,View.MeasureSpec.AT_MOST));}};headerScroll.addView(header);root.addView(headerScroll,new LinearLayout.LayoutParams(-1,-2));
  TextView title=new TextView(this);title.setText("Объекты проекта");title.setTextSize(21);header.addView(title);
  path=new TextView(this);header.addView(path);viewInfo=new TextView(this);viewInfo.setMaxLines(2);viewInfo.setEllipsize(android.text.TextUtils.TruncateAt.END);header.addView(viewInfo);selectionInfo=new TextView(this);header.addView(selectionInfo);status=new TextView(this);header.addView(status);
  LinearLayout bar=new LinearLayout(this);root.addView(bar);up=button(bar,"Вверх",()->parent());actions=button(bar,"Действия",()->menu());button(bar,"Закрыть",()->finish());
  searchButton=button(header,"Поиск и фильтры",()->searchOptions());dateButton=button(header,"Даты KML",()->dateOptions());
  list=new ListView(this);adapter=new Rows();list.setAdapter(adapter);root.addView(list,new LinearLayout.LayoutParams(-1,0,1));
  button(root,"Проекты, импорт и экспорт",()->{refreshOnResume=true;getSharedPreferences("org.rabochaya.projects.ProjectsActivity",0).edit().putLong("project",project).putString("folder","").commit();startActivity(new Intent().setClassName(this,"org.rabochaya.projects.ProjectsActivity"));});
  load();
 }
 private EditText input(){EditText field=new EditText(this);field.setImeOptions(field.getImeOptions()|android.view.inputmethod.EditorInfo.IME_FLAG_NO_EXTRACT_UI|android.view.inputmethod.EditorInfo.IME_FLAG_NO_FULLSCREEN);return field;}
 private ScrollView scroll(View child){ScrollView scroll=new ScrollView(this);scroll.addView(child);return scroll;}
 private void font(View view){if(view instanceof TextView){TextView text=(TextView)view;int style=text.getTypeface()==null?0:text.getTypeface().getStyle();android.graphics.Typeface expected=android.graphics.Typeface.create(WorkspaceUi.font(this),style);if(!expected.equals(text.getTypeface()))text.setTypeface(expected);}if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++)font(group.getChildAt(i));}}
 private void watchFont(View root){root.getViewTreeObserver().addOnGlobalLayoutListener(()->font(root));font(root);}
 private void dialogPadding(View view,Map<View,int[]> saved){saved.put(view,new int[]{view.getPaddingLeft(),view.getPaddingTop(),view.getPaddingRight(),view.getPaddingBottom(),view instanceof EditText?((EditText)view).getMinLines():-1});if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++)dialogPadding(group.getChildAt(i),saved);}}
 private void styleDialog(AlertDialog dialog){
  View decor=dialog.getWindow().getDecorView();watchFont(decor);
  View custom=decor.findViewById(android.R.id.custom);if(custom==null)return;
  Map<View,int[]> saved=new LinkedHashMap<>();dialogPadding(custom,saved);boolean editable=false;for(View view:saved.keySet())if(view instanceof EditText)editable=true;if(!editable)return;
  View title=decor.findViewById(getResources().getIdentifier("topPanel","id","android")),buttons=decor.findViewById(getResources().getIdentifier("buttonPanel","id","android"));
  if(buttons!=null)saved.put(buttons,new int[]{buttons.getPaddingLeft(),buttons.getPaddingTop(),buttons.getPaddingRight(),buttons.getPaddingBottom(),-1});
  int oldTitle=title==null?View.GONE:title.getVisibility(),oldWidth=dialog.getWindow().getAttributes().width,oldHeight=dialog.getWindow().getAttributes().height;
  android.graphics.drawable.Drawable oldBackground=decor.getBackground();android.content.res.TypedArray colors=obtainStyledAttributes(new int[]{android.R.attr.colorBackground});int background=colors.getColor(0,0xff303030);colors.recycle();boolean[] compact={false};
  decor.getViewTreeObserver().addOnGlobalLayoutListener(()->{
   android.graphics.Rect frame=new android.graphics.Rect();decor.getWindowVisibleDisplayFrame(frame);boolean small=getResources().getConfiguration().orientation==android.content.res.Configuration.ORIENTATION_LANDSCAPE&&frame.height()<WorkspaceUi.dp(this,200);
   if(small==compact[0])return;compact[0]=small;
   // At a short IME viewport, keep real 48dp action targets and one editable line.
   // The normal title/background/spacing return when the keyboard is dismissed.
   if(title!=null)title.setVisibility(small?View.GONE:oldTitle);
   for(Map.Entry<View,int[]> entry:saved.entrySet()){View view=entry.getKey();int[] p=entry.getValue();view.setPadding(p[0],small?(view instanceof EditText?2:0):p[1],p[2],small?(view instanceof EditText?2:0):p[3]);if(view instanceof EditText&&p[4]>=0)((EditText)view).setMinLines(small?1:p[4]);}
   dialog.getWindow().setBackgroundDrawable(small?new android.graphics.drawable.ColorDrawable(background):oldBackground);dialog.getWindow().setLayout(small?-1:oldWidth,small?-2:oldHeight);
  });
 }
 private AlertDialog.Builder dialog(){return new AlertDialog.Builder(this){public AlertDialog create(){AlertDialog dialog=super.create();dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);return dialog;}public AlertDialog show(){AlertDialog dialog=super.show();styleDialog(dialog);return dialog;}};}
 private Button button(LinearLayout parent,String title,Runnable action){Button b=new Button(this);b.setText(title);b.setAllCaps(false);parent.addView(b);b.setOnClickListener(v->{if(!busy)action.run();});return b;}
 private void enabled(boolean yes){busy=!yes;actions.setEnabled(yes&&snapshot!=null);up.setEnabled(yes&&!folder.isEmpty());list.setEnabled(yes);searchButton.setEnabled(yes&&listing!=null);dateButton.setEnabled(yes&&listing!=null);if(adapter!=null)adapter.notifyDataSetChanged();}
 private void load(){if(busy)return;enabled(false);status.setText("Чтение локального проекта…");worker.execute(()->{ProjectStore store=new ProjectStore(this);try{KmlProject p=store.load(project);final Element root=p.root();final List<ObjectTree.Row> data=ObjectTree.rows(root);final String token=ObjectTree.token(root);final ObjectListing index=ObjectListing.build(root,data);runOnUiThread(()->{if(disposed)return;if(expected==null||!expected.equals(token))folder="";snapshot=root;rows=data;listing=index;expected=token;if(!folder.isEmpty()&&(listing.get(folder)==null||!listing.get(folder).row.folder))folder="";selected.clear();rememberView();render();enabled(true);status.setText("Флажки — выбор, долгое нажатие — действия, «Открыть» — вход в папку");});}catch(Exception error){runOnUiThread(()->{if(disposed)return;enabled(true);status.setText(error.getMessage());dialog().setMessage("Не удалось открыть менеджер: "+error.getMessage()).setPositiveButton("Повторить",(d,w)->load()).setNegativeButton("Закрыть",(d,w)->finish()).show();});}finally{store.close();}});}
 private List<ObjectTree.Row> visible=new ArrayList<>();
 private int outsideSelection(){int n=0;for(String key:selected)if(!shownKeys.contains(key))n++;return n;}
 private void selectionSummary(){selectionInfo.setText("Выбрано: "+selected.size()+" · вне списка: "+outsideSelection());}
 private void render(){visible=new ArrayList<>();shownKeys.clear();if(listing==null)return;for(ObjectListing.Item item:listing.select(folder,viewOptions)){visible.add(item.row);shownKeys.add(item.row.key);}String title=folder.isEmpty()?"Корень проекта":listing.get(folder).row.name;
  dateButton.setText(viewOptions.dates.mode==0?"Даты KML":"Даты KML · "+KmlTimeFilter.MODES[viewOptions.dates.mode]+(viewOptions.dates.mode==2?" UTC: "+(viewOptions.dates.from.isEmpty()?"…":viewOptions.dates.from)+" — "+(viewOptions.dates.to.isEmpty()?"…":viewOptions.dates.to):""));path.setText(title+" · показано: "+visible.size());String summary=(viewOptions.query.isEmpty()?"":ObjectListing.SEARCH_FIELDS[viewOptions.searchField]+": «"+viewOptions.query+"». ")+ObjectListing.KINDS[viewOptions.kind]+" · "+ObjectListing.VISIBILITY[viewOptions.visibility]+" · "+(viewOptions.recursive?"С вложенными папками":"Эта папка")+" · "+ObjectListing.SORTS[viewOptions.sort]+(viewOptions.foldersFirst?" · Папки вначале":"");if(viewOptions.dates.mode!=0)summary+=" · "+KmlTimeFilter.MODES[viewOptions.dates.mode]+(viewOptions.dates.mode==2?" UTC: "+(viewOptions.dates.from.isEmpty()?"…":viewOptions.dates.from)+" — "+(viewOptions.dates.to.isEmpty()?"…":viewOptions.dates.to):"");viewInfo.setText(summary);viewInfo.setVisibility(viewOptions.filtered()||viewOptions.sort!=0||viewOptions.foldersFirst?View.VISIBLE:View.GONE);selectionSummary();status.setText("Выбрано: "+selected.size());up.setEnabled(!busy&&!folder.isEmpty());adapter.notifyDataSetChanged();}
 private void navigate(String key){folder=key;viewOptions=new ObjectListing.Options("",0,0,viewOptions.sort,false,viewOptions.foldersFirst);rememberView();render();}
 private void parent(){if(folder.isEmpty())return;int slash=folder.lastIndexOf('/');navigate(slash<0?"":folder.substring(0,slash));}
 private final class Rows extends BaseAdapter {
  public int getCount(){return visible.size();}public Object getItem(int i){return visible.get(i);}public long getItemId(int i){return i;}
  public View getView(int i,View old,android.view.ViewGroup parent){ObjectTree.Row row=visible.get(i);LinearLayout line=new LinearLayout(ObjectManagerActivity.this);line.setGravity(Gravity.CENTER_VERTICAL);
   CheckBox check=new CheckBox(ObjectManagerActivity.this);ObjectListing.Item item=listing.get(row.key);check.setText(row.name+"\n"+ObjectListing.KINDS[item.kind]+(item.visible?"":" · Скрыто по KML")+(viewOptions.recursive?"\n"+item.path:""));check.setMaxLines(3);check.setEllipsize(android.text.TextUtils.TruncateAt.END);check.setChecked(selected.contains(row.key));check.setEnabled(!busy);line.addView(check,new LinearLayout.LayoutParams(0,-2,1));check.setOnCheckedChangeListener((b,on)->{if(busy)return;if(on)selected.add(row.key);else selected.remove(row.key);selectionSummary();status.setText("Выбрано: "+selected.size());});
   View.OnLongClickListener context=v->{if(busy||snapshot==null)return true;if(!selected.contains(row.key)){selected.clear();selected.add(row.key);render();}rowMenu(row);return true;};
   line.setOnLongClickListener(context);check.setOnLongClickListener(context);
   if(row.folder){Button open=button(line,"Открыть",()->navigate(row.key));open.setOnLongClickListener(context);}return line;
  }
 }
 private void rowMenu(ObjectTree.Row row){
  List<String> titles=new ArrayList<>();List<Runnable> commands=new ArrayList<>();
  if(row.folder){titles.add("Открыть эту папку");commands.add(()->navigate(row.key));}
  titles.add("Переименовать выбранное");commands.add(()->name(true));titles.add("Изменить описание");commands.add(()->description());
  titles.add("Копировать");commands.add(()->capture(false));titles.add("Вырезать");commands.add(()->capture(true));titles.add("Перенести выбранное");commands.add(()->destination());
  titles.add("Показать выбранные");commands.add(()->visibility(true));titles.add("Скрыть выбранные");commands.add(()->visibility(false));titles.add("Удалить выбранное");commands.add(()->confirmDelete());
  dialog().setTitle("Действия с выбором · "+selected.size()+" · вне списка "+outsideSelection()).setItems(titles.toArray(new String[0]),(d,w)->{if(!busy)commands.get(w).run();}).setNegativeButton("Отмена",null).show();
 }
 private void menu(){
  String[] choices={"Новая папка / группа","Выбрать показанные","Снять весь выбор","Перенести выбранное","Удалить выбранное","Переименовать выбранное","Перечитать список","Копировать","Вырезать","Вставить в эту папку","Очистить буфер","Показать выбранные","Скрыть выбранные","Изменить описание"};
  dialog().setTitle("Действия · выбрано "+selected.size()+" · вне списка "+outsideSelection()).setItems(choices,(d,w)->{if(busy)return;switch(w){case 0:name(false);break;case 1:for(ObjectTree.Row r:visible)selected.add(r.key);render();break;case 2:selected.clear();render();break;case 3:destination();break;case 4:confirmDelete();break;case 5:name(true);break;case 6:load();break;case 7:capture(false);break;case 8:capture(true);break;case 9:paste();break;case 10:clearClipboard();break;case 11:visibility(true);break;case 12:visibility(false);break;case 13:description();break;}}).setNegativeButton("Отмена",null).show();
 }
 private void visibility(boolean show){final List<String> keys=selection();if(keys==null)return;try{ObjectVisibility.Preview change=ObjectVisibility.preview(snapshot,keys,show,expected);String inherited=show&&change.selectedStillHidden>0?" Из-за скрытых родителей останется скрыто выбранных элементов: "+change.selectedStillHidden+". Родительские папки автоматически не раскрываются.":"";if(change.changed==0){notice("Собственная видимость выбранных элементов уже "+(show?"включена.":"выключена.")+inherited);return;}String text="Выбрано строк: "+change.selected+", вне списка: "+outsideSelection()+". Будет изменена собственная видимость: "+change.changed+". По KML станет видимыми строк и папок: "+change.shown+", скрытыми: "+change.hidden+". Содержимое выбранных папок учитывается через наследование; собственные настройки остальных элементов сохранятся."+inherited;dialog().setTitle(show?"Показать выбранные?":"Скрыть выбранные?").setMessage(text).setPositiveButton(show?"Показать":"Скрыть",(d,w)->write(show?"show":"hide",keys,"")).setNegativeButton("Отмена",null).show();}catch(Exception e){notice(e.getMessage());}}
 private void capture(boolean cut){final List<String> keys=selection();if(keys==null)return;final String token=expected;enabled(false);status.setText("Запоминание выбора…");worker.execute(()->{ProjectStore store=new ProjectStore(this);try{ObjectClipboardWrites.capture(store,project,cut,keys,token);runOnUiThread(()->{if(disposed)return;enabled(true);status.setText((cut?"Вырезание подготовлено":"Выбор скопирован в буфер")+". Откройте папку назначения и выберите «Вставить в эту папку». При изменении проекта повторите выбор.");});}catch(Exception e){clipboardError(e);}finally{store.close();}});}
 private void clearClipboard(){enabled(false);worker.execute(()->{ProjectStore store=new ProjectStore(this);try{ObjectClipboardWrites.clear(store);runOnUiThread(()->{if(disposed)return;enabled(true);status.setText("Буфер объектов очищен");});}catch(Exception e){clipboardError(e);}finally{store.close();}});}
 private void clipboardError(Exception e){runOnUiThread(()->{if(disposed)return;enabled(true);status.setText(e.getMessage());notice(e.getMessage());});}
 private void paste(){final String token=expected,destination=folder;final Element view=snapshot;enabled(false);worker.execute(()->{ProjectStore store=new ProjectStore(this);try{ObjectClipboard clip=ObjectClipboardWrites.get(store);if(clip==null)throw new IllegalStateException("Буфер объектов пуст");if(clip.project!=project)throw new IllegalStateException("Буфер относится к другому проекту");if(!clip.token.equals(token))throw new IllegalStateException("Проект изменился после заполнения буфера. Повторите выбор и копирование или вырезание");final String fingerprint=clip.fingerprint();final int total=ObjectTree.selectedCount(view,clip.keys);runOnUiThread(()->{if(disposed)return;enabled(true);dialog().setTitle(clip.cut?"Перенести из буфера?":"Создать копии из буфера?").setMessage("Объектов и папок с содержимым: "+total+". Вставить в открытую папку? Видимость будет зависеть от неё."+(clip.cut?" Исходные объекты будут перенесены после подтверждения.":" Имена и ссылки на файлы вложений сохранятся; идентификаторы копий будут новыми.")).setPositiveButton("Вставить",(d,w)->write("paste",Collections.singletonList(fingerprint),destination)).setNegativeButton("Отмена",null).show();});}catch(Exception e){clipboardError(e);}finally{store.close();}});}
 private void name(boolean rename){
  if(rename&&selected.size()!=1){notice("Выберите один объект");return;}
  String key=rename?selected.iterator().next():folder;EditText input=input();input.setHint(rename?"Новое название":"Название папки / группы");input.setSingleLine(true);if(rename)for(ObjectTree.Row r:rows)if(r.key.equals(key))input.setText(r.name);
  AlertDialog dialog=dialog().setTitle(rename?"Переименовать":"Новая папка / группа").setView(input).setPositiveButton("Сохранить",null).setNegativeButton("Отмена",null).create();
  dialog.setOnShowListener(d->{styleDialog(dialog);dialog.getButton(-1).setOnClickListener(v->{String title=input.getText().toString();if(title.trim().isEmpty()||title.trim().length()>1000){input.setError("Название: от 1 до 1000 символов");return;}dialog.dismiss();write(rename?"rename":"create",Collections.singletonList(key),title);});});dialog.show();
 }
 private void description(){
  if(selected.size()!=1){notice("Выберите один объект или папку");return;}final String key=selected.iterator().next();
  try{String text=ObjectDescription.read(snapshot,key,expected);LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.setPadding(16,8,16,8);
   TextView help=new TextView(this);help.setText("Исходный текст описания KML. HTML и ссылки показаны как текст. Служебные ссылки вложений сохраняются отдельно. Пустой текст очищает описание.");form.addView(help);
   EditText input=input();input.setHint("Описание объекта");input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);input.setMinLines(4);input.setMaxLines(9);input.setGravity(Gravity.TOP);input.setText(text);form.addView(input);
   AlertDialog dialog=dialog().setTitle("Описание объекта").setView(scroll(form)).setPositiveButton("Сохранить",null).setNegativeButton("Отмена",null).create();
   dialog.setOnShowListener(d->{styleDialog(dialog);dialog.getButton(-1).setOnClickListener(v->{String value=input.getText().toString();try{ObjectDescription.validate(value);}catch(IllegalArgumentException error){input.setError(error.getMessage());return;}dialog.dismiss();write("description",Collections.singletonList(key),value);});});dialog.show();
  }catch(Exception error){notice(error.getMessage());}
 }
 private List<String> selection(){if(selected.isEmpty()){notice("Выберите объекты");return null;}return new ArrayList<>(selected);}
 private void destination(){final List<String> keys=selection();if(keys==null)return;List<String> paths=new ArrayList<>(),names=new ArrayList<>();paths.add("");names.add("Корень проекта");
  Map<String,String> labels=new HashMap<>();labels.put("","Корень проекта");for(ObjectTree.Row r:rows){String label=labels.get(r.parent)+" / "+r.name;labels.put(r.key,label);if(!r.folder)continue;boolean inside=false;for(String key:keys)if(r.key.equals(key)||r.key.startsWith(key+"/"))inside=true;if(!inside){paths.add(r.key);names.add(label);}}
  dialog().setTitle("Перенести в папку").setItems(names.toArray(new String[0]),(d,w)->{String destination=paths.get(w);dialog().setMessage("Перенести выбранные объекты ("+keys.size()+", вне списка: "+outsideSelection()+") в «"+names.get(w)+"»? Видимость будет зависеть от новой папки.").setPositiveButton("Перенести",(a,b)->write("move",keys,destination)).setNegativeButton("Отмена",null).show();}).setNegativeButton("Отмена",null).show();
 }
 private void confirmDelete(){final List<String> keys=selection();if(keys==null)return;try{int total=ObjectTree.selectedCount(snapshot,keys);dialog().setTitle("Удалить выбранное?").setMessage("Будет удалено объектов и папок: "+total+", включая содержимое выбранных папок. Выбранных строк вне списка: "+outsideSelection()+". Отмены после сохранения нет. Файлы вложений останутся в проекте.").setPositiveButton("Удалить",(d,w)->write("delete",keys,"")).setNegativeButton("Отмена",null).show();}catch(Exception e){notice(e.getMessage());}}
 private void write(String operation,List<String> keys,String value){
  if(busy||snapshot==null)return;final String token=expected;enabled(false);adapter.notifyDataSetChanged();status.setText("Сохранение…");
  worker.execute(()->{ProjectStore store=new ProjectStore(this);try{KmlProject p=operation.equals("paste")?ObjectClipboardWrites.paste(store,project,value,token,keys.get(0)):ObjectTreeWrites.apply(store,project,operation,keys,value,token);Element root=p.root();
    final List<ObjectTree.Row> data=ObjectTree.rows(root);final String newToken=ObjectTree.token(root);final ObjectListing index=ObjectListing.build(root,data);
    runOnUiThread(()->{if(disposed)return;snapshot=root;rows=data;listing=index;expected=newToken;folder="";selected.clear();rememberView();enabled(true);render();status.setText("Изменения сохранены");});
   }catch(Exception e){runOnUiThread(()->{if(disposed)return;enabled(true);adapter.notifyDataSetChanged();status.setText("Изменения не сохранены: "+e.getMessage());notice(e.getMessage());});}finally{store.close();}});
 }
 private SharedPreferences viewPrefs(){return getSharedPreferences("object-manager-view",0);}
 private void restoreView(){SharedPreferences prefs=viewPrefs();String prefix=project+"_";try{folder=prefs.getString(prefix+"folder","");if(folder==null)folder="";expected=prefs.getString(prefix+"token",null);viewOptions=new ObjectListing.Options(prefs.getString(prefix+"query",""),prefs.getInt(prefix+"kind",0),prefs.getInt(prefix+"visibility",0),prefs.getInt(prefix+"sort",0),prefs.getBoolean(prefix+"recursive",false),prefs.getBoolean(prefix+"foldersFirst",false),prefs.getInt(prefix+"searchField",0),prefs.getInt(prefix+"dateMode",0),prefs.getString(prefix+"dateFrom",""),prefs.getString(prefix+"dateTo",""));}catch(RuntimeException bad){folder="";expected=null;viewOptions=ObjectListing.Options.defaults();}}

 private void rememberView(){String prefix=project+"_";viewPrefs().edit().putString(prefix+"folder",folder).putString(prefix+"token",expected).putString(prefix+"query",viewOptions.query).putInt(prefix+"searchField",viewOptions.searchField).putInt(prefix+"dateMode",viewOptions.dates.mode).putString(prefix+"dateFrom",viewOptions.dates.from).putString(prefix+"dateTo",viewOptions.dates.to).putInt(prefix+"kind",viewOptions.kind).putInt(prefix+"visibility",viewOptions.visibility).putInt(prefix+"sort",viewOptions.sort).putBoolean(prefix+"recursive",viewOptions.recursive).putBoolean(prefix+"foldersFirst",viewOptions.foldersFirst).commit();}
 private Spinner option(LinearLayout form,String title,String[] names,int current){TextView label=new TextView(this);label.setText(title);form.addView(label);Spinner spinner=new Spinner(this);spinner.setContentDescription(title);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,names);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);spinner.setAdapter(adapter);spinner.setSelection(current);form.addView(spinner);return spinner;}
 private CheckBox option(LinearLayout form,String title,boolean current){CheckBox box=new CheckBox(this);box.setText(title);box.setChecked(current);form.addView(box);return box;}
 private void searchOptions(){
  LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.setPadding(16,8,16,8);EditText query=input();query.setSingleLine(true);query.setHint("Текст для поиска");query.setContentDescription("Текст для поиска");query.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(256)});query.setText(viewOptions.query);form.addView(query);
  Spinner searchField=option(form,"Искать в",ObjectListing.SEARCH_FIELDS,viewOptions.searchField);
  Spinner kind=option(form,"Тип объектов",ObjectListing.KINDS,viewOptions.kind),visibility=option(form,"Видимость объектов",ObjectListing.VISIBILITY,viewOptions.visibility),sort=option(form,"Порядок списка",ObjectListing.SORTS,viewOptions.sort);
  CheckBox recursive=option(form,"С вложенными папками",viewOptions.recursive),first=option(form,"Папки вначале",viewOptions.foldersFirst);ScrollView scroll=new ScrollView(this);scroll.addView(form);
  dialog().setTitle("Поиск и фильтры").setView(scroll).setPositiveButton("Применить",(d,w)->{viewOptions=new ObjectListing.Options(query.getText().toString(),kind.getSelectedItemPosition(),visibility.getSelectedItemPosition(),sort.getSelectedItemPosition(),recursive.isChecked(),first.isChecked(),searchField.getSelectedItemPosition(),viewOptions.dates.mode,viewOptions.dates.from,viewOptions.dates.to);rememberView();render();}).setNeutralButton("Сбросить",(d,w)->{viewOptions=ObjectListing.Options.defaults();rememberView();render();}).setNegativeButton("Отмена",null).show();
 }

 private EditText dateInput(LinearLayout form,String title,String value){TextView label=new TextView(this);label.setText(title);form.addView(label);EditText input=input();input.setSingleLine(true);input.setHint("ГГГГ-ММ-ДД");input.setContentDescription(title);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(10)});input.setText(value);form.addView(input);return input;}
 private ObjectListing.Options withDates(int mode,String from,String to){return new ObjectListing.Options(viewOptions.query,viewOptions.kind,viewOptions.visibility,viewOptions.sort,viewOptions.recursive,viewOptions.foldersFirst,viewOptions.searchField,mode,from,to);}
 private void dateOptions(){
  LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.setPadding(16,8,16,8);TextView info=new TextView(this);info.setText("Собственные TimeStamp / TimeSpan объекта. Это не дата создания файла. Период задаётся целыми днями UTC, обе даты включены. Пустая граница не ограничивает период.");form.addView(info);
  Spinner mode=option(form,"Отбор по дате",KmlTimeFilter.MODES,viewOptions.dates.mode);EditText from=dateInput(form,"С даты (UTC)",viewOptions.dates.from),to=dateInput(form,"По дату (UTC)",viewOptions.dates.to);TextView error=new TextView(this);error.setTextColor(0xffb00020);form.addView(error);
  mode.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int position,long id){from.setEnabled(position==2);to.setEnabled(position==2);error.setText("");}public void onNothingSelected(AdapterView<?> p){}});
  ScrollView scroll=new ScrollView(this);scroll.addView(form);AlertDialog dialog=dialog().setTitle("Даты KML").setView(scroll).setPositiveButton("Применить",null).setNeutralButton("Сбросить даты",(d,w)->{viewOptions=withDates(0,"","");rememberView();render();}).setNegativeButton("Отмена",null).create();
  dialog.setOnShowListener(d->{styleDialog(dialog);dialog.getButton(-1).setOnClickListener(v->{try{ObjectListing.Options next=withDates(mode.getSelectedItemPosition(),from.getText().toString(),to.getText().toString());viewOptions=next;rememberView();render();dialog.dismiss();}catch(IllegalArgumentException bad){error.setText(bad.getMessage());}});});dialog.show();
 }

 private void notice(String text){dialog().setMessage(text).setPositiveButton("Понятно",null).show();}
 protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("folder",folder);out.putString("token",expected);rememberView();}
 protected void onResume(){super.onResume();if(refreshOnResume&&!busy){refreshOnResume=false;load();}}
 public void onBackPressed(){if(busy)return;if(viewOptions.filtered()){viewOptions=new ObjectListing.Options("",0,0,viewOptions.sort,false,viewOptions.foldersFirst);rememberView();render();return;}if(!folder.isEmpty())parent();else super.onBackPressed();}
 protected void onDestroy(){disposed=true;worker.shutdown();super.onDestroy();}
}
